INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(115958, 'ruRU', '', 'Отличная работа, это должно удержать сдерживающие системы Хранилища в рабочем состоянии, пока мы не вернём его под контроль. Теперь найди и победи предательницу!', 24330),
(115959, 'ruRU', '', 'Другие Стражи говорят мне, что третий подуровень нашего хранилища пострадал особенно сильно, и что некоторые его системы скоро могут потерять питание.', 24330),
(115960, 'ruRU', '', 'Я хочу, чтобы ты проник внутрь и выполнил процедуру передачи энергии. Процедура достаточно проста; но меры безопасности суровы.', 24330),
(115961, 'ruRU', '', 'Утончённость — не из качеств Стража Мираны.', 24330),
(115962, 'ruRU', '', 'Отличная работа. Теперь найди и победи предательницу.', 24330),
(115963, 'ruRU', '', 'Будучи квартирмейстером, я была обязана выдавать и обучать всех Стражей использованию лунной глефы.', 24330),
(115964, 'ruRU', '', 'Нас осталось так мало, что нам нужно собрать всё оружие, какое можем найти. Проникни в хранилище и верни лунные глефы наших павших сестёр.', 24330),
(115965, 'ruRU', '', 'Я узнаю стража, что последним держал эти лунные глефы, по одному лишь взгляду. Я выдавала и обучала каждую из них.', 24330),
(115967, 'ruRU', '', 'Подозреваю, не всем Демоноослепленным удалось сбежать из своей тюрьмы. Обычно я оставила бы пленников на их судьбу, но охотник на демонов, таящийся во тьме — опасность слишком великая, чтобы её оставить.', 24330),
(115968, 'ruRU', '', 'Найди путь в крыло охотников на демонов и разберись с тем, что осталось в тенях.', 24330),
(115969, 'ruRU', '', 'Меня пугает мысль о том, во что превратилось бы это создание, если бы его оставили на демоническое пропитание.', 24330),
(115970, 'ruRU', '', 'Благодаря тебе мы никогда этого не узнаем. Теперь найди предательницу, заставь её заплатить за то, что она сотворила.', 24330),
(115971, 'ruRU', '', 'Я получила донесения, что особенно проблемный пленник почти совершил побег. К счастью, одна из защитных мер Хранилища удерживает его в ловушке.', 24330),
(115972, 'ruRU', '', 'Разумеется, поле не будет держать вечно. Отправляйся в Хранилище и разберись с этим существом раз и навсегда.', 24330),
(115973, 'ruRU', '', 'Отлично сражался. Теперь прикончи предательницу.', 24330),
(115981, 'ruRU', '', 'За Великого мастера!', 24330),
(115982, 'ruRU', '', 'За Великого мастера!', 24330),
(115992, 'ruRU', '', 'Не бойся, $c, мы отомстим за Расколотый берег, и я буду рядом с тобой, когда этот день придёт.', 24330),
(116001, 'ruRU', '', 'Победи демона, затем выполни последовательность запуска, чтобы восстановить питание хранилища.', 24330),
(116002, 'ruRU', '', 'Ох и... прости за эту последовательность. Страж Малис очень любит головоломки.', 24330),
(116114, 'ruRU', '', 'Ты свирепа для такого малыша, дворф. Что здесь случилось?', 24330),
(116142, 'ruRU', '', 'Ах, мой герой возвращается!', 24330),
(116151, 'ruRU', '', 'В Каменном Очаге пропали несколько изыскателей, но у них нет никаких идей.', 24330),
(116156, 'ruRU', '', 'Иди же, верни своё оружие и уничтожь демоническую мразь, что охотится за ним.', 24330),
(116164, 'ruRU', '', 'Приберите за собой, плотские дети, и перестаньте сбрасывать свой мусор в мои владения!', 24330),
(116239, 'ruRU', '', 'Вложи в это всю спину!', 24330),
(116241, 'ruRU', '', 'Какой прекрасный хаос! Давай обчистим карманы нескольким стражникам. Ставлю, мы обнаружим переодетых культистов!', 24330),
(116281, 'ruRU', '', 'Есть причина, почему мы живём на противоположном конце города, друг мой.', 24330),
(116282, 'ruRU', '', 'Я мог бы многое изменить для нашего народа... да...', 24330),
(116291, 'ruRU', '', 'Спасибо, герой. Я была бы следующей трапезой этого монстра!', 24330),
(116301, 'ruRU', '', 'Братья и сёстры, мы встречаемся сегодня вечером в "Свинье и дудке". Глашатай ждёт!', 24330),
(116302, 'ruRU', '', 'Итак, культисты встречаются в "Свинье и дудке". Идём! Глашатай у нас в руках...', 24330),
(116303, 'ruRU', '', 'Ещё одна группа! Они же не могут приходить вечно... правда?', 24330),
(116312, 'ruRU', '', 'Готов вернуться на Шэнь-Цзинь Су?', 24330),
(116313, 'ruRU', '', 'Нет! Сёстры... отомстите... за меня!', 24330),
(116316, 'ruRU', '', 'Обычно требуется время, чтобы обучить новые войска, но для тебя я ускорил этот процесс, Великий мастер.', 24330),
(116317, 'ruRU', '', 'Отличный выбор, Великий мастер. Я с радостью исследую любые дополнительные улучшения для твоего орденского зала.', 24330),
(116320, 'ruRU', '', 'Принеси мне немного кожи, и я с радостью обменяю её на мой Амарантовый хмель.', 24330),
(116379, 'ruRU', '', 'Прошу, $n — достань остальных! Бедные Верон и Ярлин! Я не знаю, куда их увели!', 24330),
(116380, 'ruRU', '', 'Ух, ты точно смелый! Спасибо за помощь!', 24330);
